\set ON_ERROR_STOP on
\pset pager off
\timing on

-- Performance fixtures only. Not a Liquibase migration.
-- Uses a dedicated project and deterministic UUIDs generated by md5(text)::uuid.
-- Rerunning after successful COMMIT deliberately fails; run cleanup first.
BEGIN;

DO $guard$
BEGIN
  IF EXISTS (SELECT 1 FROM projects WHERE id = '00000000-0000-4000-8000-00000000f011')
     OR EXISTS (SELECT 1 FROM users WHERE id = '00000000-0000-4000-8000-00000000f001') THEN
    RAISE EXCEPTION 'Performance fixtures already exist. Run 003-performance-cleanup.sql first.';
  END IF;
END;
$guard$;

INSERT INTO users(id,email,password_hash,display_name,created_at,updated_at)
VALUES ('00000000-0000-4000-8000-00000000f001','performance-fixture@example.test',
        'not-a-real-login-hash','Performance Test User',now(),now());

INSERT INTO projects(id,name,created_by,status,created_at,updated_at)
VALUES ('00000000-0000-4000-8000-00000000f011','PERFORMANCE TEST - TEMPORARY',
        '00000000-0000-4000-8000-00000000f001','active',now(),now());

INSERT INTO project_members(project_id,user_id,role,joined_at)
VALUES ('00000000-0000-4000-8000-00000000f011',
        '00000000-0000-4000-8000-00000000f001','owner',now());

INSERT INTO specifications(id,project_id,uploaded_by,version,title,content)
VALUES ('00000000-0000-4000-8000-00000000f021',
        '00000000-0000-4000-8000-00000000f011',
        '00000000-0000-4000-8000-00000000f001',1,
        'Performance specification','Synthetic workload for SQL query profiling');

INSERT INTO backlogs(id,project_id,specification_id,version,status)
VALUES ('00000000-0000-4000-8000-00000000f031',
        '00000000-0000-4000-8000-00000000f011',
        '00000000-0000-4000-8000-00000000f021',1,'draft');

-- 12,000 tasks across several status values.
INSERT INTO tasks(id,backlog_id,task_type,title,description,status,priority,sort_order)
SELECT md5('perf-task-' || g)::uuid,
       '00000000-0000-4000-8000-00000000f031'::uuid,
       'task','Performance task ' || g,
       repeat('Synthetic task description. ',5),
       (ARRAY['draft','ready','in_progress','in_review','done'])[1 + (g % 5)],
       (1 + (g % 5))::smallint, g
FROM generate_series(1,12000) g;

-- 3,000 decisions, representative for project-scoped filtering.
INSERT INTO architectural_decisions(id,project_id,decision_key,title,status,created_by)
SELECT md5('perf-decision-' || g)::uuid,
       '00000000-0000-4000-8000-00000000f011'::uuid,
       'PERF-' || g,'Performance architecture decision ' || g,
       (ARRAY['proposed','accepted','rejected','superseded'])[1 + (g % 4)],
       '00000000-0000-4000-8000-00000000f001'::uuid
FROM generate_series(1,3000) g;

INSERT INTO chat_sessions(id,project_id,created_by,title)
VALUES ('00000000-0000-4000-8000-00000000f041',
        '00000000-0000-4000-8000-00000000f011',
        '00000000-0000-4000-8000-00000000f001','Performance chat');

-- 10,000 messages for one session.
INSERT INTO chat_messages(id,project_id,session_id,author_id,sender,content,created_at)
SELECT md5('perf-message-' || g)::uuid,
       '00000000-0000-4000-8000-00000000f011'::uuid,
       '00000000-0000-4000-8000-00000000f041'::uuid,
       CASE WHEN g % 2 = 0 THEN '00000000-0000-4000-8000-00000000f001'::uuid ELSE NULL END,
       CASE WHEN g % 2 = 0 THEN 'user' ELSE 'assistant' END,
       'Synthetic chat message ' || g,
       now() - interval '30 days' + g * interval '1 second'
FROM generate_series(1,10000) g;

-- 4,000 completed operations and associated review events.
INSERT INTO ai_operations(id,project_id,initiated_by,operation_type,status,provider,model_name,
                          input_tokens,output_tokens,duration_ms,created_at,started_at,finished_at)
SELECT md5('perf-operation-' || g)::uuid,
       '00000000-0000-4000-8000-00000000f011'::uuid,
       '00000000-0000-4000-8000-00000000f001'::uuid,
       'task_decomposition','completed','synthetic','benchmark-only',
       400 + g % 200,100 + g % 75,1500 + g % 500,
       now()-interval '60 days' + g*interval '1 minute',
       now()-interval '60 days' + g*interval '1 minute' + interval '1 second',
       now()-interval '60 days' + g*interval '1 minute' + interval '3 seconds'
FROM generate_series(1,4000) g;

INSERT INTO review_events(id,ai_operation_id,reviewer_id,outcome,duration_ms,corrections_count)
SELECT md5('perf-review-' || g)::uuid,
       md5('perf-operation-' || g)::uuid,
       '00000000-0000-4000-8000-00000000f001'::uuid,
       (ARRAY['accepted','modified','rejected'])[1 + (g % 3)],
       CASE WHEN g % 11 = 0 THEN NULL ELSE (800 + g % 2000)::bigint END,
       g % 4
FROM generate_series(1,4000) g;

-- 12,000 pending outbox rows; valid JSONB envelopes.
INSERT INTO outbox_events(id,project_id,event_type,aggregate_type,aggregate_id,deduplication_key,payload,
                          status,created_at,next_attempt_at)
SELECT md5('perf-outbox-' || g)::uuid,
       '00000000-0000-4000-8000-00000000f011'::uuid,
       'github.issue.create','task',md5('perf-task-' || g)::uuid,
       'perf-outbox-' || g,
       jsonb_build_object('event_id','perf-event-'||g,'schema_version',1,
                          'occurred_at','2026-11-15T12:00:00Z',
                          'data',jsonb_build_object('task_id',g)),
       'pending',now() - interval '2 days' + (g % 1000) * interval '1 second',
       now() - interval '1 day' + (g % 1000) * interval '1 second'
FROM generate_series(1,12000) g;

COMMIT;

ANALYZE tasks;
ANALYZE architectural_decisions;
ANALYZE chat_messages;
ANALYZE ai_operations;
ANALYZE review_events;
ANALYZE outbox_events;

SELECT 'tasks' AS entity,count(*) AS fixture_rows FROM tasks WHERE backlog_id='00000000-0000-4000-8000-00000000f031'
UNION ALL SELECT 'decisions',count(*) FROM architectural_decisions WHERE project_id='00000000-0000-4000-8000-00000000f011'
UNION ALL SELECT 'messages',count(*) FROM chat_messages WHERE session_id='00000000-0000-4000-8000-00000000f041'
UNION ALL SELECT 'operations',count(*) FROM ai_operations WHERE project_id='00000000-0000-4000-8000-00000000f011'
UNION ALL SELECT 'reviews',count(*) FROM review_events r JOIN ai_operations a ON a.id=r.ai_operation_id WHERE a.project_id='00000000-0000-4000-8000-00000000f011'
UNION ALL SELECT 'outbox',count(*) FROM outbox_events WHERE project_id='00000000-0000-4000-8000-00000000f011';
\echo Performance fixtures committed. Run benchmarks next; cleanup afterward.
